from PIL import Image
img = Image.open('/app/output/final_poster.png')
W, H = img.size

regions = [
    ('header',      0,    400),
    ('metrics',     400,  1200),
    ('content1',   1200,  2400),
    ('performance',2400,  3600),
    ('risks',      3600,  4800),
    ('framework',  4800,  6000),
    ('footer',     H-200,  H),
]

for name, y0, y1 in regions:
    crop = img.crop((0, y0, W, y1))
    colors = crop.getcolors(maxcolors=100000)
    if colors:
        top5 = sorted(colors, key=lambda x: -x[0])[:5]
        def rgb(c):
            if isinstance(c, tuple) and len(c) >= 3:
                return '#{:02x}{:02x}{:02x}'.format(c[0],c[1],c[2])
            return str(c)
        print(f'{name}: {len(colors)} colors, top: {[(c,rgb(rgb_c)) for c,rgb_c in top5[:3]]}')
    else:
        print(f'{name}: too many colors')
"

