from PIL import Image
img = Image.open('/app/output/final_poster.png')
W, H = img.size

def classify(r,g,b):
    if r < 50 and g < 80: return 'NAVY'
    if r > 180 and g < 130: return 'AMBER'
    if 60 < r < 130 and 100 < g < 160: return 'TEAL'
    if r > 230 and g > 230 and b > 230: return 'WH'
    if r > 200: return 'OFFW'
    return f'({r},{g},{b})'

# Framework section: y=4200-4600
print('=== FRAMEWORK SECTION (y=4200-4600) ===')
for y in range(4200, 4600, 50):
    samples = {}
    for x in range(100, W-100, 200):
        c = classify(*img.getpixel((x, y)))
        samples[c] = samples.get(c, 0) + 1
    non_basic = {k:v for k,v in samples.items() if k not in ('WH',)}
    if non_basic:
        print(f'  y={y}: {non_basic}')
    else:
        print(f'  y={y}: (white background)')

# Also verify that the text areas at bottom of poster (risks/framework) have TEAL
print()
print('=== RISK SECTION AREA (y=1700-2100) ===')
for y in range(1700, 2100, 50):
    samples = {}
    for x in range(100, W-100, 200):
        c = classify(*img.getpixel((x, y)))
        samples[c] = samples.get(c, 0) + 1
    non_basic = {k:v for k,v in samples.items() if k not in ('WH',)}
    if non_basic:
        print(f'  y={y}: {non_basic}')
"

